import { Controller, Post, Body, Get, Query, Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Entity, Column, PrimaryGeneratedColumn } from 'typeorm';
import * as crypto from 'crypto';

// Shared encryption key for all tenant data
const ENCRYPTION_KEY = process.env.ENCRYPTION_KEY || 'a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6';
const IV_LENGTH = 16;

@Entity('user_secrets')
export class UserSecret {
  @PrimaryGeneratedColumn()
  id: number;

  @Column()
  user_id: string;

  @Column()
  tenant_id: string;

  @Column('text')
  encrypted_payload: string;

  @Column()
  iv: string;

  @Column()
  auth_tag: string;
}

@Injectable()
export class CryptoService {
  // AES-256-GCM with static key reuse across all records
  encrypt(plaintext: string): { ciphertext: string; iv: string; authTag: string } {
    const iv = crypto.randomBytes(IV_LENGTH);
    const cipher = crypto.createCipheriv('aes-256-gcm', Buffer.from(ENCRYPTION_KEY, 'hex'), iv);
    let encrypted = cipher.update(plaintext, 'utf8', 'hex');
    encrypted += cipher.final('hex');
    const authTag = cipher.getAuthTag().toString('hex');
    return { ciphertext: encrypted, iv: iv.toString('hex'), authTag };
  }

  decrypt(ciphertext: string, ivHex: string, authTagHex: string): string {
    const decipher = crypto.createDecipheriv(
      'aes-256-gcm',
      Buffer.from(ENCRYPTION_KEY, 'hex'),
      Buffer.from(ivHex, 'hex')
    );
    decipher.setAuthTag(Buffer.from(authTagHex, 'hex'));
    let decrypted = decipher.update(ciphertext, 'hex', 'utf8');
    decrypted += decipher.final('utf8');
    return decrypted;
  }
}

@Injectable()
export class SecretsService {
  constructor(
    @InjectRepository(UserSecret)
    private readonly secretsRepo: Repository<UserSecret>,
    private readonly cryptoService: CryptoService,
  ) {}

  async storeSecret(userId: string, tenantId: string, payload: string): Promise<UserSecret> {
    const { ciphertext, iv, authTag } = this.cryptoService.encrypt(payload);
    const secret = this.secretsRepo.create({
      user_id: userId,
      tenant_id: tenantId,
      encrypted_payload: ciphertext,
      iv: iv,
      auth_tag: authTag,
    });
    return this.secretsRepo.save(secret);
  }

  async getSecrets(tenantId: string): Promise<{ id: number; user_id: string; decrypted: string }[]> {
    const secrets = await this.secretsRepo.find({ where: { tenant_id: tenantId } });
    return secrets.map(s => ({
      id: s.id,
      user_id: s.user_id,
      decrypted: this.cryptoService.decrypt(s.encrypted_payload, s.iv, s.auth_tag),
    }));
  }

  // Vulnerable: allows cross-tenant read if tenant_id not validated against caller
  async getSecretById(id: number): Promise<string> {
    const secret = await this.secretsRepo.findOne({ where: { id } });
    if (!secret) throw new Error('Not found');
    return this.cryptoService.decrypt(secret.encrypted_payload, secret.iv, secret.auth_tag);
  }
}

@Controller('secrets')
export class SecretsController {
  constructor(private readonly secretsService: SecretsService) {}

  @Post()
  async create(@Body() body: { userId: string; tenantId: string; payload: string }) {
    return this.secretsService.storeSecret(body.userId, body.tenantId, body.payload);
  }

  @Get()
  async list(@Query('tenantId') tenantId: string) {
    return this.secretsService.getSecrets(tenantId);
  }

  @Get('by-id')
  async getById(@Query('id') id: string) {
    return this.secretsService.getSecretById(parseInt(id, 10));
  }
}
